15: namespace Serilog.Context;
16: 
17: /// <summary>
18: /// Holds ambient properties that can be attached to log events. To
19: /// configure, use the <see cref="Serilog.Configuration.LoggerEnrichmentConfiguration.FromLogContext"/> method.
20: /// </summary>
21: /// <example>
22: /// Configuration:
23: /// <code lang="C#">
24: /// var log = new LoggerConfiguration()
25: ///     .Enrich.FromLogContext()
26: ///     ...
27: /// </code>
28: /// Usage:
29: /// <code lang="C#">
30: /// using (LogContext.PushProperty("MessageId", message.Id))
31: /// {
32: ///     Log.Information("The MessageId property will be attached to this event");
33: /// }
34: /// </code>
35: /// </example>
36: /// <remarks>The scope of the context is the current logical thread, using AsyncLocal
37: /// (and so is preserved across async/await calls).</remarks>
38: public static class LogContext
39: {
40:     static readonly AsyncLocal<EnricherStack?> Data = new();
41: 
42:     /// <summary>
43:     /// Push a property onto the context, returning an <see cref="IDisposable"/>
